#include "milp/CuttingPlane.hpp"
#include <cassert>
using namespace sovereign;
static Model fractional(){Model m;m.sense=Sense::Minimize;m.variables.push_back({0,0,"x",VariableType::Integer,0,INF,true});m.variables.push_back({1,1,"y",VariableType::Binary,0,1,true});m.objective[0]=-3;m.objective[1]=-2;Constraint c;c.name="capacity";c.coefficients[0]=2;c.coefficients[1]=2;c.relation=Relation::LessEqual;c.rhs=3;m.constraints.push_back(c);return m;}
int main(){auto m=fractional();auto before=m.variables[0].type;auto lp=LPSolver{}.solve(relaxMILP(m),LPMethod::RevisedSimplex,10000,&m);assert(lp.status==LPStatus::Optimal);assert(!lp.gomoryRows.empty());Constraint cut;std::size_t source=0;assert(GomoryCutGenerator{}.generate(lp,relaxMILP(m),cut,source));double lhs=0;for(auto p:cut.coefficients)lhs+=p.second*lp.solution.primal[p.first];assert(cut.rhs-lhs>1e-8);auto r=CuttingPlaneSolver{}.solve(m);assert(r.status==CuttingStatus::OptimalInteger);assert(r.cutsAccepted>0&&r.lpSolves>1);assert(r.verified);assert(m.variables[0].type==before);assert(std::abs(r.objective+3)<1e-8);
 Model integral;integral.variables.push_back({0,0,"x",VariableType::Integer,0,5,true});integral.objective[0]=1;Constraint c;c.coefficients[0]=1;c.relation=Relation::GreaterEqual;c.rhs=2;integral.constraints.push_back(c);auto ri=CuttingPlaneSolver{}.solve(integral);assert(ri.status==CuttingStatus::OptimalInteger&&ri.cutsAccepted==0&&ri.verified);return 0;}
